CREATE TABLE public.invoice_payment_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),store_id uuid NOT NULL DEFAULT public.current_store_id() REFERENCES public.stores(id),document_id uuid NOT NULL REFERENCES public.sales_documents(id),payment_id uuid NOT NULL UNIQUE REFERENCES public.customer_payments(id),amount numeric NOT NULL CHECK(amount>0),client_ref uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(store_id,client_ref));
GRANT SELECT ON public.invoice_payment_allocations TO authenticated; GRANT ALL ON public.invoice_payment_allocations TO service_role;
ALTER TABLE public.invoice_payment_allocations ENABLE ROW LEVEL SECURITY;
CREATE POLICY allocations_read ON public.invoice_payment_allocations FOR SELECT TO authenticated USING(store_id=public.current_store_id() AND public.is_staff(auth.uid()));
CREATE OR REPLACE FUNCTION public.invoice_outstanding(p_document uuid) RETURNS numeric LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE d record; amount numeric; credits numeric; paid numeric; BEGIN SELECT * INTO d FROM public.sales_documents WHERE id=p_document AND kind='invoice' AND store_id=public.current_store_id(); IF NOT FOUND OR NOT public.is_staff(auth.uid()) THEN RAISE EXCEPTION 'Invoice not found'; END IF; IF d.sale_id IS NULL THEN RETURN NULL; END IF; SELECT coalesce(sum(p.amount/nullif(p.exchange_rate,0)),0) INTO amount FROM public.sale_payments p WHERE sale_id=d.sale_id AND public.is_account_method(method); SELECT coalesce(sum(r.amount),0) INTO credits FROM public.refunds r WHERE r.sale_id=d.sale_id AND public.is_account_method(method); SELECT coalesce(sum(a.amount),0) INTO paid FROM public.invoice_payment_allocations a WHERE document_id=d.id; RETURN greatest(round(amount-credits-paid,2),0); END $$;
REVOKE ALL ON FUNCTION public.invoice_outstanding(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.invoice_outstanding(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.receive_invoice_payment(p_document uuid,p_amount numeric,p_currency text,p_method text,p_reference text,p_client_ref uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d record; result uuid; rate numeric; usd numeric; existing record; BEGIN SELECT * INTO d FROM public.sales_documents WHERE id=p_document AND store_id=public.current_store_id() AND kind='invoice' AND status='issued' FOR UPDATE; IF NOT FOUND OR NOT public.is_staff(auth.uid()) OR p_client_ref IS NULL THEN RAISE EXCEPTION 'Invoice not available'; END IF; SELECT payment_id INTO result FROM public.invoice_payment_allocations WHERE store_id=public.current_store_id() AND client_ref=p_client_ref; IF FOUND THEN RETURN result; END IF; SELECT public.currency_rate(p_currency,zig_rate,rand_rate) INTO rate FROM public.settings WHERE store_id=public.current_store_id(); usd:=round(p_amount/rate,2); IF usd<=0 OR usd>public.invoice_outstanding(d.id)+0.005 THEN RAISE EXCEPTION 'Payment exceeds this invoice outstanding balance'; END IF; result:=public.receive_customer_payment(d.customer_id,p_amount,p_currency,p_method,p_reference); INSERT INTO public.invoice_payment_allocations(document_id,payment_id,amount,client_ref) VALUES(d.id,result,usd,p_client_ref); RETURN result; END $$;
REVOKE ALL ON FUNCTION public.receive_invoice_payment(uuid,numeric,text,text,text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.receive_invoice_payment(uuid,numeric,text,text,text,uuid) TO authenticated;